import unittest

from invoice_client import InvoiceClient


class FakeTransport:
    def __init__(self):
        self.calls = []

    def request(self, path, *, retries=0):
        self.calls.append((path, retries))
        return {"id": path.rsplit("/", 1)[-1]}


class InvoiceClientTest(unittest.TestCase):
    def test_fetch_uses_two_retries(self):
        transport = FakeTransport()
        result = InvoiceClient(transport).fetch_invoice("inv-7")
        self.assertEqual({"id": "inv-7"}, result)
        self.assertEqual([("/invoices/inv-7", 2)], transport.calls)


if __name__ == "__main__":
    unittest.main()
